const $=id=>document.getElementById(id);
const ids=['cylinders','displacement','pattern','idle','limit','inertia','length','muffling','intake','variation','blend','volume'];
const defaults={v8:[8,5,'cross',850,7000,.25,1.8,35,25,12],i4:[4,2,'even',950,8500,.15,1.2,25,40,8],v6:[6,3.5,'even',800,7200,.22,1.6,40,30,10],v10:[10,5.2,'even',1000,10000,.18,1,15,45,6],twin:[2,1.2,'twin',750,6000,.4,2.2,20,20,22]};
let ctx,node,master,filter,resonance,delay,feedback,intake,analyser,recorder,destination,sampleBuffer,sampleSource,sampleGain;
let running=false,rpm=0,phase=0,held=false,blipTimer,recording=false,toastTimer;
function config(){return Object.fromEntries([...ids,'throttle'].map(id=>[id,id==='pattern'?$(id).value:Number($(id).value)]));}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4500);}
function update(){const c=config();for(const id of ids){const o=$(id+'-out');if(o)o.textContent=id==='idle'||id==='limit'?c[id].toLocaleString()+' RPM':id==='inertia'?c[id].toFixed(2)+' kg·m²':id==='length'?c[id].toFixed(1)+' m':c[id]+'%';}$('throttle-out').textContent=c.throttle+'%';$('load').textContent=c.throttle+'%';$('engine-name').textContent=c.displacement.toFixed(1)+' L '+(c.pattern==='cross'&&c.cylinders===8?'CROSS-PLANE V8':c.pattern==='twin'&&c.cylinders===2?'V-TWIN':c.cylinders===4?'INLINE-FOUR':c.cylinders+' CYLINDER');
if(node){node.port.postMessage({config:c});const t=ctx.currentTime;master.gain.setTargetAtTime(c.volume/100*.7,t,.03);filter.frequency.setTargetAtTime(700+(100-c.muffling)*65,t,.04);resonance.frequency.setTargetAtTime(Math.min(1800,343/(4*c.length)),t,.04);delay.delayTime.setTargetAtTime(c.length/343,t,.04);feedback.gain.setTargetAtTime(.12+(100-c.muffling)/400,t,.04);intake.gain.setTargetAtTime(c.intake/100*.5,t,.04);sampleGain.gain.setTargetAtTime(sampleBuffer&&running?c.blend/100*.5:0,t,.04);}}
async function initAudio(){if(ctx){await ctx.resume();return;}ctx=new AudioContext({latencyHint:'interactive'});try{await ctx.audioWorklet.addModule('./engine-worklet.js');}catch(e){await ctx.close();ctx=null;throw new Error('Audio initialization failed. Open this app through its web address.');}node=new AudioWorkletNode(ctx,'engine-processor',{outputChannelCount:[2]});master=ctx.createGain();master.gain.value=0;filter=ctx.createBiquadFilter();filter.type='lowpass';resonance=ctx.createBiquadFilter();resonance.type='peaking';resonance.Q.value=1.2;resonance.gain.value=6;delay=ctx.createDelay(.1);feedback=ctx.createGain();intake=ctx.createGain();const airFilter=ctx.createBiquadFilter();airFilter.type='highpass';airFilter.frequency.value=1300;const compressor=ctx.createDynamicsCompressor();compressor.threshold.value=-12;compressor.ratio.value=5;analyser=ctx.createAnalyser();analyser.fftSize=2048;destination=ctx.createMediaStreamDestination();sampleGain=ctx.createGain();sampleGain.gain.value=0;node.connect(filter).connect(resonance).connect(compressor);resonance.connect(delay).connect(feedback).connect(delay);feedback.connect(compressor);node.connect(airFilter).connect(intake).connect(compressor);sampleGain.connect(compressor);compressor.connect(master).connect(analyser);master.connect(ctx.destination);master.connect(destination);node.port.onmessage=e=>{rpm=e.data.rpm;phase=e.data.phase;if(sampleSource)sampleSource.playbackRate.setTargetAtTime(Math.max(.15,rpm/2000),ctx.currentTime,.08);};update();await ctx.resume();}
function sampleLoop(){if(sampleSource){sampleSource.stop();sampleSource.disconnect();sampleSource=null;}if(sampleBuffer&&ctx){sampleSource=ctx.createBufferSource();sampleSource.buffer=sampleBuffer;sampleSource.loop=true;sampleSource.connect(sampleGain);sampleSource.start();}}
$('start').onclick=async()=>{try{await initAudio();running=!running;node.port.postMessage({on:running});if(running&&sampleBuffer&&!sampleSource)sampleLoop();$('start').textContent=running?'◉ Stop engine':'◉ Start engine';$('live-badge').textContent=running?'ENGINE RUNNING':'IGNITION OFF';$('live-badge').classList.toggle('on',running);$('status').textContent=running?'SYSTEM RUNNING':'SYSTEM STANDBY';update();}catch(e){toast(e.message);}};
ids.forEach(id=>$(id).addEventListener('input',()=>{update();try{localStorage.setItem('engine-lab-build',JSON.stringify(config()));}catch{}}));$('throttle').oninput=update;
$('preset').onchange=()=>{const values=defaults[$('preset').value];ids.slice(0,10).forEach((id,i)=>$(id).value=values[i]);update();};
function setThrottle(v){$('throttle').value=v;update();}
$('blip').onclick=()=>{if(!running){toast('Start the engine to blip the throttle.');return;}clearTimeout(blipTimer);const before=$('throttle').value;setThrottle(100);blipTimer=setTimeout(()=>setThrottle(before),650);};
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();if(!held){held=true;setThrottle(100);}}});window.addEventListener('keyup',e=>{if(e.code==='Space'&&held){held=false;setThrottle(0);}});window.addEventListener('blur',()=>{if(held){held=false;setThrottle(0);}});
async function loadSample(file){if(!file)return;if(file.size>30*1024*1024){toast('Choose a sound smaller than 30 MB.');return;}try{await initAudio();sampleBuffer=await ctx.decodeAudioData(await file.arrayBuffer());sampleLoop();$('sample-name').textContent=file.name;$('blend').value=35;update();toast('Custom layer loaded. Its pitch follows engine speed.');}catch{toast('Could not decode this sound. Try a WAV, MP3, or OGG file.');}}
$('sample').onchange=e=>loadSample(e.target.files[0]);$('upload-label').ondragover=e=>{e.preventDefault();};$('upload-label').ondrop=e=>{e.preventDefault();loadSample(e.dataTransfer.files[0]);};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('save').onclick=()=>download(new Blob([JSON.stringify({version:1,config:config()},null,2)],{type:'application/json'}),'engine-lab-build.json');
function applyConfig(c){if(!c||typeof c!=='object')throw new Error('Invalid build');for(const id of ids){if(c[id]===undefined)continue;const el=$(id);if(el.tagName==='SELECT'){if([...el.options].some(o=>o.value===String(c[id])))el.value=c[id];}else if(Number.isFinite(Number(c[id]))){el.value=Math.max(Number(el.min),Math.min(Number(el.max),Number(c[id])));}}update();}
$('import').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==1||!data.config)throw new Error();applyConfig(data.config);toast('Engine build imported. Custom audio files are loaded separately.');}catch{toast('Choose a valid Engine Lab build JSON file.');}e.target.value='';};
$('record').onclick=async()=>{if(recording){recorder.stop();return;}if(!running){toast('Start the engine before recording.');return;}if(typeof MediaRecorder==='undefined'){toast('Recording is unavailable in this browser.');return;}try{const chunks=[];recorder=new MediaRecorder(destination.stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{download(new Blob(chunks,{type:recorder.mimeType}),'engine-lab-recording.'+(recorder.mimeType.includes('mp4')?'mp4':'webm'));recording=false;$('record').textContent='● Record';$('record').classList.remove('recording');};recorder.start();recording=true;$('record').textContent='■ Stop & save';$('record').classList.add('recording');toast('Recording engine audio. Click Stop & save to download.');}catch(e){toast('Recording could not start: '+e.message);}};
function fit(canvas){const ratio=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);}const g=canvas.getContext('2d');g.setTransform(ratio,0,0,ratio,0,0);return [g,w,h];}
function draw(){const c=config();$('rpm').textContent=Math.round(rpm).toLocaleString();$('firing').textContent=(rpm*c.cylinders/120).toFixed(0)+' Hz';$('rpm-fill').style.width=Math.min(100,rpm/c.limit*100)+'%';$('rpm-fill').style.background=rpm>c.limit*.92?'#ff9676':'#d3f879';const [g,w,h]=fit($('engine'));g.clearRect(0,0,w,h);g.strokeStyle='#2a352c';g.lineWidth=.6;for(let x=0;x<w;x+=24){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke();}for(let y=0;y<h;y+=24){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke();}
const n=c.cylinders,cw=Math.min(45,(w-45)/Math.ceil(n/2)),start=w/2-Math.ceil(n/2)*cw/2;g.font='8px monospace';g.textAlign='center';
for(let k=0;k<n;k++){const row=k%2,col=Math.floor(k/2),x=start+col*cw+cw/2,y=row?150:35;const offset=c.pattern==='twin'&&n===2?(k?315/720:0):k/n;const p=((phase-offset)%1+1)%1;const crank=p*Math.PI*4;const travel=(1-Math.cos(crank))*19;const firing=running&&p<.08;g.fillStyle=firing?'#d3f879':'#344333';g.globalAlpha=firing?.3:1;g.fillRect(x-cw*.34,y,cw*.68,68);g.globalAlpha=1;g.strokeStyle=firing?'#d3f879':'#66755e';g.lineWidth=1;g.strokeRect(x-cw*.34,y,cw*.68,68);g.fillStyle=firing?'#e2ffa6':'#a6b39d';g.fillRect(x-cw*.29,y+8+travel,cw*.58,10);g.strokeStyle='#90a482';g.lineWidth=3;g.beginPath();g.moveTo(x,y+18+travel);g.lineTo(x+Math.sin(crank)*8,y+82);g.stroke();g.fillStyle='#718368';g.fillText(String(k+1).padStart(2,'0'),x,y-10);g.strokeStyle='#596b50';g.lineWidth=1;g.beginPath();g.arc(x+Math.sin(crank)*8,y+82,8,0,Math.PI*2);g.stroke();}
g.strokeStyle='#708665';g.lineWidth=2;for(let row=0;row<2;row++){g.beginPath();g.moveTo(start-10,row?232:117);g.lineTo(w-start+10,row?232:117);g.stroke();}const [s,sw,sh]=fit($('scope'));s.clearRect(0,0,sw,sh);s.strokeStyle='#2d372c';s.lineWidth=.5;for(let x=0;x<sw;x+=32){s.beginPath();s.moveTo(x,0);s.lineTo(x,sh);s.stroke();}for(let y=sh/2%24;y<sh;y+=24){s.beginPath();s.moveTo(0,y);s.lineTo(sw,y);s.stroke();}const data=new Float32Array(2048);if(analyser)analyser.getFloatTimeDomainData(data);s.beginPath();s.lineWidth=1.2;s.strokeStyle='#c4e991';for(let i=0;i<data.length;i++){let x=i/data.length*sw,y=sh/2+data[i]*sh*1.6;i?s.lineTo(x,y):s.moveTo(x,y);}s.stroke();requestAnimationFrame(draw);}
try{const saved=localStorage.getItem('engine-lab-build');if(saved)applyConfig(JSON.parse(saved));}catch{}update();draw();
